/* activerooms-20261029d (Dan, Oct 29 2026): d = no Re-enter button, the room name is the clickable re-enter control; all text inherits the .hrhint size (9px in the final .hrw rules) so it matches 'Pick a room type' / My rooms; wide name box, members ellipsize first; badge slot only if r.badge exists. c = Hub Rooms look (inherits .hrw font, .hrr row, .hrbtns button), one line per room: name - people [Re-enter]; name = topic, else room type label, else short id; full id in tooltip. b: "Active rooms" list on the right of the Hub Rooms start list. Shows live pre-rooms / bot rooms the viewer is a member of (GET /api/prerooms/mine, status live) with a Re-enter button. Roll back: remove the script tag in index.html. */
(function(){var D=document,rooms=[],last=0;
function css(){if(D.getElementById('arCss'))return;var s=D.createElement('style');s.id='arCss';s.textContent='.arBox{position:absolute;top:0;left:44%;right:0;max-height:100%;overflow:auto;box-sizing:border-box;padding:0 2px;font:inherit;color:#fff;z-index:3}.arBox .arH{display:block;font:inherit;margin:0 0 3px}.arBox .arRow{display:flex;align-items:center;gap:5px;width:100%;box-sizing:border-box;font:inherit;color:#fff;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);border-radius:6px;padding:3px 6px;margin:0 0 3px;white-space:nowrap;overflow:hidden}.arBox .arRow:hover{background:rgba(var(--hub-blue-rgb),.18);border-color:rgba(var(--hub-blue-rgb),.5)}.arBox .arName{flex:0 1 auto;min-width:min(14em,70%);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:inherit;color:#fff;cursor:pointer;text-decoration:underline;text-decoration-color:rgba(255,255,255,.35);text-underline-offset:2px;border-radius:3px;outline:none}.arBox .arName:hover,.arBox .arName:focus-visible{text-decoration-color:#fff;background:rgba(var(--hub-blue-rgb),.35)}.arBox .arMem{flex:1 1 0;min-width:3em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:inherit;opacity:.8}.arBox .arBadge{flex:none;font:inherit;padding:0 5px;border-radius:7px;border:1px solid rgba(255,255,255,.25)}.arBox .arNone{font:inherit}';D.head.appendChild(s);}
function load(){if(Date.now()-last<10000)return;last=Date.now();fetch('/api/prerooms/mine',{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.ok?r.json():null;}).then(function(j){if(!j)return;var L=(j.rooms||[]).filter(function(x){return x.status==='live';});Promise.all(L.map(function(x){return fetch('/api/prerooms/'+encodeURIComponent(x.id),{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.ok?r.json():null;}).then(function(v){v=v&&(v.view||v.room||v);var p=(v&&v.live&&v.live.people)||(v&&v.roster)||[];var seen={};x.names=p.map(function(q){return q.name;}).filter(function(n){if(!n||seen[n])return false;seen[n]=1;return true;});x.live=v&&v.live?v.live.room:'';var c=v&&v.center;if(c&&c.topic)x.topic=c.topic;}).catch(function(){x.names=[];});})).then(function(){rooms=L;draw(true);});}).catch(function(){});}
function fw(){var f=D.getElementById('prFrame');return f&&f.contentWindow;}
function reenter(id){var bt=[].filter.call(D.querySelectorAll('.hrw .hrnewcol button.hrnew'),function(b){return /^Bot rooms?$/i.test(b.textContent.trim());})[0];
 if(!(window.__prActive&&fw()))if(bt)bt.click();var n=0,opened=false,t=setInterval(function(){n++;var w=fw();if(n>60){clearInterval(t);return;}
 try{if(!w||!w.prCards)return;var c=w.prCards.current&&w.prCards.current();if(!c||c.id!==id){if(!opened){opened=true;w.prCards.open(id);}return;}
 if(c.live&&w.prCards.enterLive()){clearInterval(t);}}catch(e){}},250);}
function draw(force){D.querySelectorAll('.hrw .hrnewcol').forEach(function(col){var host=col.parentElement;if(!host)return;var box=host.querySelector(':scope > .arBox');
 if(box&&!force)return;if(!box){css();if(getComputedStyle(host).position==='static')host.style.position='relative';box=D.createElement('div');box.className='arBox';host.appendChild(box);load();}
 box.innerHTML='';var h=D.createElement('div');h.className='arH';h.textContent='Active rooms';box.appendChild(h);
 if(!rooms.length){var e=D.createElement('div');e.className='arNone';e.textContent='No live rooms';box.appendChild(e);}
 rooms.forEach(function(r){var row=D.createElement('div');row.className='arRow';var full=r.live||r.id;row.title=full+(r.live&&r.id?' ('+r.id+')':'');var nm=(r.topic||r.type||'').trim()||String(full).slice(0,11);var n=D.createElement('span');n.className='arName';n.textContent=nm;n.setAttribute('role','button');n.tabIndex=0;n.setAttribute('aria-label','Re-enter '+nm);var go=function(e){e.preventDefault();e.stopPropagation();reenter(r.id);};n.addEventListener('click',go);n.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '||e.key==='Spacebar')go(e);});row.appendChild(n);if(r.names&&r.names.length){var m=D.createElement('span');m.className='arMem';m.textContent=r.names.join(', ');m.title=r.names.join(', ');row.appendChild(m);}if(r.badge){var g=D.createElement('span');g.className='arBadge';g.textContent=r.badge;row.appendChild(g);}box.appendChild(row);});});}
new MutationObserver(function(){draw(false);}).observe(D.documentElement,{childList:true,subtree:true});setInterval(function(){if(D.querySelector('.hrw .hrnewcol')){last=0;load();}},30000);draw(false);})();
